<?php if (!defined('ABSPATH')) exit; $bid=(int)$bolao->id; if(isset($_POST['rsb_add_part']) && check_admin_referer('rsb_part')){ RSB_Participantes::create(['bolao_id'=>$bid]+$_POST); echo '<div class="notice notice-success"><p>Participante adicionado.</p></div>'; } if(isset($_GET['delete']) && check_admin_referer('rsb_delete_part_'.(int)$_GET['delete'])){ RSB_Participantes::delete((int)$_GET['delete']); echo '<div class="notice notice-success"><p>Participante excluído.</p></div>'; } $items=RSB_Participantes::all($bid); ?>
<div class="wrap rsb-wrap"><h1>Participantes</h1><form method="post" class="rsb-inline"><?php wp_nonce_field('rsb_part'); ?><input name="nome" placeholder="Nome" required><input name="email" placeholder="E-mail"><input name="telefone" placeholder="Telefone"><select name="status_pagamento"><option value="pendente">Pendente</option><option value="pago">Pago</option></select><input name="valor_pago" type="number" step="0.01" placeholder="Valor pago"><button class="button button-primary" name="rsb_add_part" value="1">Adicionar</button></form>
<table class="widefat striped rsb-table"><thead><tr><th>Nome</th><th>Email</th><th>Telefone</th><th>Pagamento</th><th>Valor</th><th>Ações</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?php echo esc_html($i->nome); ?></td><td><?php echo esc_html($i->email); ?></td><td><?php echo esc_html($i->telefone); ?></td><td><span class="rsb-badge <?php echo esc_attr($i->status_pagamento); ?>"><?php echo esc_html($i->status_pagamento); ?></span></td><td><?php echo esc_html(rsb_money($i->valor_pago)); ?></td><td><a href="<?php echo esc_url(wp_nonce_url(admin_url('admin.php?page=rsb-participantes&delete='.(int)$i->id),'rsb_delete_part_'.(int)$i->id)); ?>">Excluir</a></td></tr><?php endforeach; ?></tbody></table></div>
